     1	package com.loja.strategy.payment;
     2	
     3	import com.loja.dto.CheckoutRequest;
     4	import com.loja.service.MoneyRounding;
     5	import org.springframework.stereotype.Component;
     6	import java.math.BigDecimal;
     7	import java.math.RoundingMode;
     8	
     9	@Component
    10	public class CreditCardPayment implements PaymentStrategy {
    11	    @Override
    12	    public String getCode() {
    13	        return "CREDIT_CARD";
    14	    }
    15	
    16	    @Override
    17	    public PaymentResult calculate(CheckoutRequest request, BigDecimal orderTotal, boolean hasCoupon) {
    18	        int installments = request.getInstallments() != null ? request.getInstallments() : 1;
    19	
    20	        BigDecimal finalTotal;
    21	        BigDecimal installmentAmount;
    22	
    23	        if (installments <= 3) {
    24	            finalTotal = orderTotal;
    25	            installmentAmount = MoneyRounding.round(finalTotal.divide(new BigDecimal(installments), 10, RoundingMode.HALF_EVEN));
    26	        } else {
    27	            BigDecimal rate = new BigDecimal("0.0199");
    28	            BigDecimal onePlusRate = BigDecimal.ONE.add(rate);
    29	            BigDecimal pow = onePlusRate.pow(installments);
    30	            BigDecimal numerator = orderTotal.multiply(rate);
    31	            BigDecimal denominator = BigDecimal.ONE.subtract(BigDecimal.ONE.divide(pow, 10, RoundingMode.HALF_EVEN));
    32	
    33	            installmentAmount = MoneyRounding.round(numerator.divide(denominator, 10, RoundingMode.HALF_EVEN));
    34	            finalTotal = installmentAmount.multiply(new BigDecimal(installments));
    35	        }
    36	
    37	        BigDecimal adjustment = finalTotal.subtract(orderTotal);
    38	
    39	        return new PaymentResult(adjustment, finalTotal, installments, installmentAmount);
    40	    }
    41	
    42	    @Override
    43	    public boolean isAvailable(CheckoutRequest request, BigDecimal orderTotal) {
    44	        return true;
    45	    }
    46	
    47	    @Override
    48	    public boolean isValidInstallments(int installments) {
    49	        return installments >= 1 && installments <= 12;
    50	    }
    51	}
