     3	import com.loja.dto.CheckoutRequest;
     4	import com.loja.external.TransLogClient;
     5	import org.springframework.stereotype.Component;
     6	import java.math.BigDecimal;
     7	
     8	@Component
     9	public class EconomyShipping implements ShippingStrategy {
    10	    private final TransLogClient transLogClient;
    11	
    12	    public EconomyShipping(TransLogClient transLogClient) {
    13	        this.transLogClient = transLogClient;
    14	    }
    15	
    16	    @Override
    17	    public String getCode() {
    18	        return "ECONOMY";
    19	    }
    20	
    21	    @Override
    22	    public ShippingResult calculate(CheckoutRequest request, BigDecimal totalWeightKg) {
    23	        TransLogClient.TransLogQuote quote = transLogClient.getQuote(request.getZipCode(), totalWeightKg, "STD");
    24	
    25	        if (!quote.isAvailable()) {
    26	            throw new RuntimeException("TransLog unavailable or ZIP not served");
    27	        }
    28	
    29	        int extraDays = switch (request.getRegion()) {
    30	            case "NORTH" -> 3;
    31	            case "NORTHEAST" -> 2;
    32	            default -> 0;
    33	        };
    34	
    35	        return new ShippingResult(quote.getPrice(), quote.getDeliveryDays() + extraDays);
    36	    }
    37	
    38	    @Override
    39	    public boolean isAvailable(CheckoutRequest request, BigDecimal totalWeightKg) {
    40	        TransLogClient.TransLogQuote quote = transLogClient.getQuote(request.getZipCode(), totalWeightKg, "STD");
    41	        return quote.isAvailable();
    42	    }
    43	}
