   177	    @Override
   178	    public PaymentResult calculate(CheckoutRequest request, BigDecimal orderTotal, boolean hasCoupon) {
   179	        int installments = request.getInstallments() != null ? request.getInstallments() : 1;
   180	
   181	        BigDecimal finalTotal;
   182	        BigDecimal installmentAmount;
   183	
   184	        if (installments <= 3) {
   185	            finalTotal = orderTotal;
   186	            installmentAmount = MoneyRounding.round(finalTotal.divide(new BigDecimal(installments), 10, RoundingMode.HALF_EVEN));
   187	        } else {
   188	            BigDecimal rate = new BigDecimal("0.0199");
   189	            BigDecimal onePlusRate = BigDecimal.ONE.add(rate);
   190	            BigDecimal pow = onePlusRate.pow(installments);
   191	            BigDecimal numerator = orderTotal.multiply(rate);
   192	            BigDecimal denominator = BigDecimal.ONE.subtract(BigDecimal.ONE.divide(pow, 10, RoundingMode.HALF_EVEN));
   193	
   194	            installmentAmount = MoneyRounding.round(numerator.divide(denominator, 10, RoundingMode.HALF_EVEN));
   195	            finalTotal = installmentAmount.multiply(new BigDecimal(installments));
   196	        }
   197	
   198	        BigDecimal adjustment = finalTotal.subtract(orderTotal);
   199	
   200	        return new PaymentResult(adjustment, finalTotal, installments, installmentAmount);
   201	    }
